def load() -> pd.DataFrame:
    import pandas as pd
    path = 'data/biomedical/input/1-s2.0-S0092867420301070-mmc3.xlsx'
    xl = pd.ExcelFile(path)
    rows = []
    for s in xl.sheet_names:
        df = pd.read_excel(path, sheet_name=s, header=None, nrows=5)
        rows.append({'sheet_name': s, 'ncols_first5rows': df.shape[1], 'row0': '\t'.join([str(x) for x in df.iloc[0].tolist()])})
    return pd.DataFrame(rows)

def process(loadAcetylGenes) -> pd.DataFrame:
    # Count distinct, non-empty gene symbols in the acetylproteomics significant gene list
    genes = loadAcetylGenes.copy()
    genes['gene'] = genes['gene'].astype(str).str.strip()
    genes = genes[genes['gene'].notna() & (genes['gene'] != '') & (genes['gene'].str.lower() != 'nan')]
    return pd.DataFrame([{
        'significant_gene_count': int(genes['gene'].nunique())
    }])
